import java.util.Scanner;
import java.util.ArrayList;
import java.util.HashMap;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int n = in.nextInt();
        int shard1 = in.nextInt();
        int shard2 = in.nextInt();
        int[] m = new int[n];

        for (int i=0; i<n; i++) {
            m[i] = in.nextInt();
        }

        in.nextInt();

        ArrayList<Shard> shards = new ArrayList<>(n);

        for (int i=0; i<n; i++) {
            Point[] vertices = new Point[m[i]];

            for (int j=0; j<m[i]; j++) {
                double x = in.nextDouble();
                double y = in.nextDouble();
                vertices[j] = new Point(x, y);
            }

            shards.add(new Shard(vertices, i+1));
        }

        in.close();

        Square square = new Square(shards);
        square.solve();

        double output = square.getOutput(shard1, shard2);
        System.out.printf("%.3f\n", output);
    }
}

class Square extends Shard {
    private ArrayList<Shard> availableShards;
    private ArrayList<Shard> usedShards;

    private Square() {
        super(new Point[]{
                new Point(0, 0),
                new Point(0, 120),
                new Point(120, 120),
                new Point(120, 0)
        });
    }

    public Square(ArrayList<Shard> shards) {
        this();
        this.availableShards = new ArrayList<>(shards);
        this.usedShards = new ArrayList<>();
    }

    public Square(ArrayList<Shard> availableShards, ArrayList<Shard> usedShards) {
        this();
        this.availableShards = availableShards;
        this.usedShards = usedShards;
    }

    private void lockShard(Shard shard) {
        if (availableShards.remove(shard))
            usedShards.add(shard);
    }

    private void unlockShard(Shard shard, int i) {
        if (usedShards.remove(shard))
            availableShards.add(i, shard);
    }

    public boolean solve() {
        if (availableShards.isEmpty())
            return true;

        //pick possible point with minimal remaining angle
        ConnectPointBundle bundle = getConnectPoint();
        Point connectPoint = bundle.point;

        //get possible shards based on remaining angle
        ArrayList<Point> possiblePoints = getPossiblePoints(availableShards, bundle.remainingAngle);

        if (possiblePoints.isEmpty())
            return false;

        //get edge to connect to
        Edge connectEdge = getConnectEdge(connectPoint);

        //try all vertexes of all available shards
        for (int i=0; i< availableShards.size(); i++) {
            Shard shard = availableShards.get(i);
            lockShard(shard);
            ArrayList<Shard> pastTransforms = new ArrayList<>();

            for (int j=0; j< shard.getVertices().length; j++) {
                if (!possiblePoints.contains(shard.getVertices()[j]))
                    continue;

                shard.translateTo(shard.getVertices()[j], connectPoint);

                //try rotating each vertex so it fits
                shard.rotateTo(connectPoint, shard.getEdge(j), connectEdge);
                if (tryShard(shard, pastTransforms)) return true;
                shard.rotateTo(connectPoint, shard.getEdge(j-1), connectEdge);
                if (tryShard(shard, pastTransforms)) return true;

                shard.mirrorAround(connectPoint);   //mirror shard

                shard.rotateTo(connectPoint, shard.getEdge(j), connectEdge);
                if (tryShard(shard, pastTransforms)) return true;
                shard.rotateTo(connectPoint, shard.getEdge(j-1), connectEdge);
                if (tryShard(shard, pastTransforms)) return true;
            }

            unlockShard(shard, i);
        }

        return false;
    }

    private boolean tryShard(Shard shard, ArrayList<Shard> pastTransforms) {
        //shard must be inside the square, must not be symmetric to one of the past and must not intersect with used shards
        if (isOutside(shard) || wasTriedBefore(shard, pastTransforms) || isShardIntersecting(shard))
            return false;

        pastTransforms.add(shard.deepCopy());

        //if it's the first one, add mirrored version about diagonal
        if (usedShards.size() == 1) {
            shard.mirrorAboutDiagonal();
            pastTransforms.add(shard.deepCopy());
            shard.mirrorAboutDiagonal();
        }

        //check recursively
        Square square = new Square(availableShards, usedShards);
        return square.solve();
    }

    private ConnectPointBundle getConnectPoint() {
        if (usedShards.isEmpty())
            return new ConnectPointBundle(vertices[0], Math.PI/2);

        HashMap<Point, Double> pointAngles = new HashMap<>();

        for (Shard shard: usedShards) {
            for (int i = 0; i < shard.getVertices().length; i++) {
                Point vertex = shard.getVertices()[i];
                Point point = getKeyIfContains(pointAngles, vertex);    //containsKey doesn't work

                if (point != null)
                    pointAngles.put(point, pointAngles.get(point) + shard.getAngleAtVertex(i));
                else pointAngles.put(vertex, shard.getAngleAtVertex(i));
            }
        }

        //check if there are any edges
        pointCycle:
        for (Point point: pointAngles.keySet()) {
            for (Shard shard: usedShards) {
                for (Edge edge: shard.getEdges()) {
                    if (point.intersects(edge).b) {
                        pointAngles.put(point, pointAngles.get(point) + Math.PI);
                        continue pointCycle;
                    }
                }
            }
        }

        //get the point with minimal angle
        ConnectPointBundle cp = new ConnectPointBundle(null, Math.PI);

        for (Point point: pointAngles.keySet()) {
            double remaining = getMaxAngleAtPoint(point) - pointAngles.get(point);

            //there will always exist such point
            if (remaining > 0.01 && remaining < cp.remainingAngle) {
                cp.point = point;
                cp.remainingAngle = remaining;
            }
        }

        return cp;
    }

    private Point getKeyIfContains(HashMap<Point, Double> map, Point key) {
        for (Point point: map.keySet()) {
            if (point.equals(key))
                return point;
        }

        return null;
    }

    private double getMaxAngleAtPoint(Point point) {
        //point is in the corner
        for (Point vertex: vertices) {
            if (point.equals(vertex)) return Math.PI/2;
        }

        //point is on an edge
        for (Edge edge: edges) {
            if (point.intersects(edge).b) return Math.PI;
        }

        //point is somewhere else
        return 2*Math.PI;
    }

    private static class ConnectPointBundle {
        public Point point;
        public double remainingAngle;
        public ConnectPointBundle(Point point, double remainingAngle) {
            this.point = point;
            this.remainingAngle = remainingAngle;
        }
    }

    private ArrayList<Point> getPossiblePoints(ArrayList<Shard> availableShards, double targetAngle) {
        ArrayList<Point> possiblePoints = new ArrayList<>();
        ArrayList<Shard> nextShards = new ArrayList<>(availableShards);

        for (Shard shard: availableShards) {
            nextShards.remove(shard);

            for (int j = 0; j < shard.getVertices().length; j++) {
                double vertexAngle = shard.getAngleAtVertex(j);

                if (Math.abs(targetAngle - vertexAngle) < 0.01)
                    possiblePoints.add(shard.getVertices()[j]);
                else if (targetAngle - vertexAngle > 0.01) {
                    ArrayList<Point> points = getPossiblePoints(nextShards, targetAngle - vertexAngle);

                    if (!points.isEmpty()) {
                        possiblePoints.add(shard.getVertices()[j]);
                        possiblePoints.addAll(points);
                    }
                }
            }
        }

        return possiblePoints;
    }

    private Edge getConnectEdge(Point point) {
        for (Shard shard: usedShards) {
            for (Edge edge: shard.getEdges()) {
                Edge edge1 = tryEdge(point, shard, edge);
                if (edge1 != null) return edge1;
            }
        }

        return edges[0];
    }

    private Edge tryEdge(Point point, Shard shard, Edge edge) {
        if (!edge.start.equals(point) && !edge.end.equals(point) || edge.getOverlappingEdge(this) != null)
            return null;

        for (Shard usedShard: usedShards) {
            if (usedShard == shard) continue;
            Edge overlap = edge.getOverlappingEdge(usedShard);

            if (overlap != null) {
                ArrayList<Edge.EdgePart> edgeParts = edge.getEdgeParts(overlap);

                for (Edge.EdgePart edgePart: edgeParts) {
                    if (!edgePart.isOverlap && edgePart.edge.overlaps(edge)) {
                        Edge edge1 = tryEdge(point, shard, edgePart.edge);
                        if (edge1 != null) return edge1;
                    }
                }

                return null;
            }
        }

        return edge;
    }

    private boolean isOutside(Shard shard) {
        for (Point vertex: shard.getVertices()) {
            if (vertex.x < -0.01 || vertex.x > 120.01 || vertex.y < -0.01 || vertex.y > 120.01)
                return true;
        }
        return false;
    }

    private boolean wasTriedBefore(Shard shard, ArrayList<Shard> pastTransforms) {
        for (Shard pastShard: pastTransforms) {
            if (shard.equals(pastShard))
                return true;
        }
        return false;
    }

    private boolean isShardIntersecting(Shard shard) {
        for (Shard usedShard: usedShards) {
            if (usedShard != shard && shard.intersects(usedShard))
                return true;
        }
        return false;
    }

    public double getOutput(int s1, int s2) {
        Shard shard1 = null, shard2 = null;

        //get shards with correct number
        for (Shard shard: usedShards) {
            if (shard.getNumber() == s1)
                shard1 = shard;
            else if  (shard.getNumber() == s2)
                shard2 = shard;
        }

        //calculate overlapping edges' length
        double overlapSize = 0;

        for (Edge edge: shard1.getEdges()) {
            Edge overlap = edge.getOverlappingEdge(shard2);

            if (overlap != null) {
                ArrayList<Edge.EdgePart> edgeParts = edge.getEdgeParts(overlap);

                for (Edge.EdgePart edgePart: edgeParts) {
                    if (edgePart.isOverlap) {
                        overlapSize += edgePart.edge.getVector().size();
                    }
                }
            }
        }

        return overlapSize;
    }
}

class Shard {
    protected final Point[] vertices;
    protected final Edge[] edges;
    private final double[] vertexAngles;
    private final int number;

    public Shard(Point[] vertices) {
        this.vertices = vertices;
        this.edges = createEdges();
        this.vertexAngles = calcVertexAngles();
        this.number = -1;
    }

    public Shard(Point[] vertices, int number) {
        this.vertices = vertices;
        this.edges = createEdges();
        this.vertexAngles = calcVertexAngles();
        this.number = number;
    }

    private Edge[] createEdges() {
        Edge[] edges = new Edge[vertices.length];
        for (int i = 0; i < vertices.length; i++)
            edges[i] = new Edge(vertices[i], vertices[(i+1) % vertices.length]);
        return edges;
    }

    private double[] calcVertexAngles() {
        double[] angles =  new double[vertices.length];
        for (int i = 0; i < vertices.length; i++)
            angles[i] = getVertexAngle(i);
        return angles;
    }

    public Point[] getVertices() {
        return vertices;
    }

    public Edge[] getEdges() {
        return edges;
    }

    public Edge getEdge(int i) {
        return edges[(i + edges.length) % edges.length];
    }

    public int getNumber() {
        return number;
    }

    public double getAngleAtVertex(int i) {
        return vertexAngles[i];
    }

    public void translate(double dx, double dy) {
        for (Point vertex: vertices) {
            vertex.x += dx;
            vertex.y += dy;
        }
    }

    public void translateTo(Point origin, Point target) {
        double dx = target.x - origin.x;
        double dy = target.y - origin.y;
        translate(dx, dy);
    }

    public void rotate(double rad) {
        double sin = Math.sin(rad);
        double cos = Math.cos(rad);

        for (Point vertex: vertices) {
            double x = vertex.x * cos - vertex.y * sin;
            double y = vertex.x * sin + vertex.y * cos;
            vertex.x = x;
            vertex.y = y;
        }
    }

    public void rotateAround(Point point, double rad) {
        translate(-point.x, -point.y);
        rotate(rad);
        translate(point.x, point.y);
    }

    public void rotateTo(Point around, Edge edge, Edge target) {
        Point vector = edge.getVector();
        Point targetVector = target.getVector();

        if (edge.end.equals(around))
            vector = vector.reverse();
        if (target.end.equals(around))
            targetVector = targetVector.reverse();

        double angle = Math.atan2(vector.y, vector.x);
        double targetAngle = Math.atan2(targetVector.y, targetVector.x);

        double rad = targetAngle - angle;
        rotateAround(around, rad);
    }

    public void mirror() {
        for (Point vertex: vertices) {
            vertex.x *= -1;
        }
    }

    public void mirrorAround(Point point) {
        translate(-point.x, 0);
        mirror();
        translate(point.x, 0);
    }

    public void mirrorAboutDiagonal() {
        rotate(Math.PI/4);
        mirror();
        rotate(-Math.PI/4);
    }

    public boolean intersects(Shard shard) {
        //check if any edges are intersecting
        for (Edge edge: edges) {
            for (Edge edge1: shard.getEdges()) {
                if (edge.intersects(edge1))
                    return true;
            }
        }

        //check whether one shard is in the other
        return this.overlaps(shard) || shard.overlaps(this);
    }

    public boolean overlaps(Shard shard) {
        for (Edge edge: edges) {
            //get part of edge that doesn't overlap
            Edge overlap = edge.getOverlappingEdge(shard);
            Edge difference = edge;

            if (overlap != null) {
                //get edge difference
                ArrayList<Edge.EdgePart> edgeParts = edge.getEdgeParts(overlap);
                difference = null;

                for  (Edge.EdgePart edgePart : edgeParts) {
                    if (!edgePart.isOverlap && edgePart.edge.overlaps(edge)) {
                        difference = edgePart.edge;
                        break;
                    }
                }

                if (difference == null)   //edge fully overlaps
                    continue;
            }

            //get point on the difference
            Point rayStart = difference.getCentre();

            while (rayStart.intersectsVertex(shard)) {
                difference = new Edge(rayStart, difference.end);
                rayStart = difference.getCentre();
            }

            //count intersections
            Edge ray = new Edge(rayStart, new Point(rayStart.x + 240, rayStart.y));
            int count = countRayIntersections(ray, shard);

            if (count % 2 != 0) //odd count means it's inside
                return true;
        }

        return false;
    }

    private int countRayIntersections(Edge ray, Shard shard) {
        int count = 0;

        //ray must not intersect any vertex
        while (ray.intersectsVertex(shard))
            ray.rotate(0.05);

        for (Edge edge: shard.getEdges()) {
            if (ray.intersects(edge))
                count++;
        }

        return count;
    }

    private double getVertexAngle(int i) {
        Edge edge1 = getEdge(i-1);
        Edge edge2 = getEdge(i);

        Point vector1 = edge1.getVector().reverse();
        Point vector2 = edge2.getVector();

        double s = vector1.x * vector2.x + vector1.y * vector2.y;
        double c = s / (vector1.size() * vector2.size());
        double phi = Math.acos(c);

        vector1.makeSameSizeVector(vector2);

        //check if the angle is >180°
        Point sum = new Point(vector1.x + vector2.x, vector1.y + vector2.y);
        double k = 240 / sum.size();
        Edge ray = new Edge(vertices[i], new Point(vertices[i].x + sum.x * k, vertices[i].y + sum.y * k));

        int count = countRayIntersections(ray, this);
        if (count % 2 == 0) //even count means it's aiming outside
            phi = 2*Math.PI - phi;

        return phi;
    }

    public Shard deepCopy() {
        Point[] vertices = new Point[this.vertices.length];

        for (int i = 0; i < this.vertices.length; i++) {
            vertices[i] = new Point(this.vertices[i].x, this.vertices[i].y);
        }

        return new Shard(vertices);
    }

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof Shard shard) {
            //check if vertices are equal
            if (vertices.length != shard.getVertices().length)
                return false;

            for (int i = 0; i < vertices.length; i++) {
                if (vertices[0].equals(shard.getVertices()[i])) {
                    //if one vertex is equal, check the others (in both directions)
                    for (int j = 1; j < vertices.length; j++) {
                        if (!vertices[j].equals(shard.getVertices()[(i + j) % vertices.length]) &&
                                !vertices[j].equals(shard.getVertices()[(i - j + vertices.length) % vertices.length]))
                            return false;
                    }

                    return true;
                }
            }
        }

        return false;
    }
}

class Edge {
    public final Point start;
    public final Point end;

    public Edge(Point start, Point end) {
        this.start = start;
        this.end = end;
    }

    public Edge(Point end) {
        this(new Point(0, 0), end);
    }

    public Point getVector() {
        return new Point(
                end.x - start.x,
                end.y - start.y
        );
    }

    public Point getCentre() {
        return new Point((start.x + end.x)/2, (start.y + end.y)/2);
    }

    public void rotate(double rad) {
        //rotates end around start
        end.x -= start.x;
        end.y -= start.y;

        double sin = Math.sin(rad);
        double cos = Math.cos(rad);
        double x = end.x * cos - end.y * sin;
        double y = end.x * sin + end.y * cos;
        end.x = x;
        end.y = y;

        end.x += start.x;
        end.y += start.y;
    }

    public boolean intersects(Edge edge) {
        Point vector1 = getVector();
        Point vector2 = edge.getVector();

        if (vector1.isVectorSame(vector2))  //edges are parallel
            return false;

        //edges aren't parallel
        double dx = start.x - edge.start.x;
        double dy = start.y - edge.start.y;
        double t = (vector2.y * dx - vector2.x * dy) / (vector2.x * vector1.y - vector1.x * vector2.y);
        double s = (vector1.x * dy - vector1.y * dx) / (vector1.x * vector2.y - vector2.x * vector1.y);

        return Math.abs(0.5 - t) < 0.499 && Math.abs(0.5 - s) < 0.499;
    }

    public boolean overlaps(Edge edge) {
        Point vector1 = getVector();
        Point vector2 = edge.getVector();

        //non-parallel edges can't overlap
        if (!vector1.isVectorSame(vector2))
            return false;

        if ((start.equals(edge.start) && end.equals(edge.end)) ||
                (start.equals(edge.end) && end.equals(edge.start)))
            return true;

        return start.intersects(edge).b || end.intersects(edge).b ||
                edge.start.intersects(this).b || edge.end.intersects(this).b;
    }

    public Edge getOverlappingEdge(Shard shard) {
        for (Edge edge: shard.getEdges()) {
            if (this.overlaps(edge))
                return edge;
        }
        return null;
    }

    public ArrayList<EdgePart> getEdgeParts(Edge edge) {
        Point.IntersectBundle start = edge.start.intersects(this);
        Point.IntersectBundle end = edge.end.intersects(this);
        Point.IntersectBundle myStart = this.start.intersects(edge);
        Point.IntersectBundle myEnd = this.end.intersects(edge);

        ArrayList<PointIntersection> intersections = new ArrayList<>();

        intersections.add(new PointIntersection(this.start, new Point.IntersectBundle(myStart.b, 0)));
        intersections.add(new PointIntersection(this.end, new Point.IntersectBundle(myEnd.b, 1)));
        intersections.add(new PointIntersection(edge.start, start));
        intersections.add(new PointIntersection(edge.end, end));

        intersections.sort((i1, i2) -> (Math.abs(i1.bundle.t - i2.bundle.t) < 0.001) ?
                0 : (i1.bundle.t < i2.bundle.t) ? -1 : 1);

        Point[] points = intersections.stream().map(i -> i.point).toList().toArray(new Point[0]);
        ArrayList<EdgePart> parts = new ArrayList<>();

        if (intersections.get(1).bundle.b)
            parts.add(new EdgePart(new Edge(points[0], points[1]), false));
        parts.add(new EdgePart(new Edge(points[1], points[2]), true));
        if (intersections.get(2).bundle.b)
            parts.add(new EdgePart(new Edge(points[2], points[3]), false));

        return parts;
    }

    private static class PointIntersection {
        public Point point;
        public Point.IntersectBundle bundle;
        public PointIntersection(Point point, Point.IntersectBundle bundle) {this.point = point;this.bundle = bundle;}
    }

    public static class EdgePart {
        public Edge edge;
        public boolean isOverlap;    //true - overlap, false - difference
        public EdgePart(Edge edge, boolean isOverlap) {this.edge = edge;this.isOverlap = isOverlap;}
    }

    public boolean intersectsVertex(Shard shard) {
        for (Point vertex: shard.getVertices()) {
            if (vertex.intersects(this).b)
                return true;
        }

        return false;
    }
}

//can be used either as point or vector
class Point {
    public double x;
    public double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public Point reverse() {
        //get opposite vector
        return new Point(-x, -y);
    }

    public double size() {
        //vector size
        return Math.pow(x*x + y*y, 0.5);
    }

    public boolean isVectorSame(Point vector) {
        if (Math.abs(vector.x) < 0.01) return Math.abs(x) < 0.01;
        double k = x / vector.x;
        return Math.abs(vector.y * k - y) < 0.01;
    }

    public void makeSameSizeVector(Point vector) {
        double k = vector.size() / size();
        x *= k;
        y *= k;
    }

    public IntersectBundle intersects(Edge edge) {
        Point vector = edge.getVector();
        Edge edge1 = new Edge(vector);
        Edge pointEdge = new Edge(new Point(x - edge.start.x, y - edge.start.y));

        if (Math.abs(vector.x) < 0.01 || Math.abs(vector.y) < 0.01) {
            edge1.rotate(Math.PI/4);
            pointEdge.rotate(Math.PI/4);
        }

        IntersectBundle bundle = new IntersectBundle();
        bundle.t = pointEdge.end.x / vector.x;
        double s = pointEdge.end.y / vector.y;
        bundle.b = Math.abs(bundle.t - s) < 0.01 && Math.abs(0.5 - bundle.t) < 0.499;

        return bundle;
    }

    public static class IntersectBundle {
        public boolean b;
        public double t;
        public IntersectBundle() {}
        public IntersectBundle(boolean b, double t) {this.b = b;this.t = t;}
    }

    public boolean intersectsVertex(Shard shard) {
        for (Point vertex: shard.getVertices()) {
            if (this.equals(vertex))
                return true;
        }

        return false;
    }

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof Point point) {
            if (Math.abs(point.x - x) < 0.01 && Math.abs(point.y - y) < 0.01)
                return true;
        }

        return super.equals(obj);
    }
}
